/-- Image of the stated Gaussian completion over legal prognostic functions. -/
def gaussianLawClass (d : ℕ) (hd : 0 < d) (s : ℝ) : Set (OutcomeLaw d) :=
  {P | ∃ m : CenteredL2Fn d, SobolevClass d s m ∧ P = gaussianOutcomeLaw hd m}

