  -- @realizes R(infimum over all admissible designs of fixed-function worst risk)
/-- Worst risk of a specified design. -/
def worstLoss (π : Design n d) (s : ℝ) : ℝ≥0∞ :=
  ⨆ m : {m : CenteredL2Fn d // SobolevClass d s m}, loss π m.val.val

