/-- Pair-cosine indices and positive integer frequencies. -/
abbrev PairIdx (d L : ℕ) :=
  {α : (Fin d × Fin d) × (Fin L × Fin L) // α.1.1 < α.1.2}

8b4b25bed0de550c.statement:
/-- Fixed-law worst excess, outside the experiment expectation. -/
def publishedWorst {n d : ℕ} (π : Design n d) (C : Set (OutcomeLaw d)) : ℝ≥0∞ :=
  ⨆ P : C, excess π P.val

